/* 生成的图层（见 assets/prompts/），已裁切、压缩，作为 data URI 放进页面。 */
(() => { const A = (window.YL.ASSET_DATA = window.YL.ASSET_DATA || {});
A["sea_water"] = "data:image/jpeg;base64,";
A["sea_eye"] = "data:image/jpeg;base64,";
A["sea_whale"] = "data:image/webp;base64,";
(window.YL.ASSET_SIZE = window.YL.ASSET_SIZE || {}); Object.assign(window.YL.ASSET_SIZE, {"sea_water": [1024, 3072], "sea_eye": [1536, 1024], "sea_whale": [3072, 560]});
})();
